	TestCreateAccount(t)
	TestListAccounts(t)
	TestCheckFraud(t)
	TestGetAlerts(t)
	TestGetInterestNotFound(t)
	TestGetDailyReport(t)
	TestGetMonthlyReport(t)

	log.Println("=" * 60)
	log.Println("✅ 모든 테스트 완료!")
