// 사기 탐지 컴포넌트

import React, { useState, useEffect } from "react";
import api from "../services/api";
import { FraudAlert } from "../types";

const FraudDetection: React.FC = () => {
  const [amount, setAmount] = useState("");
  const [frequency, setFrequency] = useState("0");
  const [balanceDrain, setBalanceDrain] = useState("0");
  const [result, setResult] = useState<any>(null);
  const [alerts, setAlerts] = useState<FraudAlert[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadingAlerts, setLoadingAlerts] = useState(false);

  useEffect(() => {
    loadAlerts();
  }, []);

  const loadAlerts = async () => {
    setLoadingAlerts(true);
    try {
      const data = await api.getFraudAlerts();
      setAlerts(data);
    } catch (error) {
      console.error("Failed to load fraud alerts:", error);
    } finally {
      setLoadingAlerts(false);
    }
  };

  const handleCheck = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const fraudResult = await api.checkFraud(
        parseFloat(amount) || 0,
        parseInt(frequency) || 0,
        parseFloat(balanceDrain) || 0
      );
      setResult(fraudResult);
      loadAlerts();
    } catch (error) {
      console.error("Fraud check failed:", error);
    } finally {
      setLoading(false);
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case "critical":
        return "#e74c3c";
      case "high":
        return "#f39c12";
      case "medium":
        return "#f1c40f";
      case "low":
        return "#2ecc71";
      default:
        return "#95a5a6";
    }
  };

  const getSeverityEmoji = (severity: string) => {
    switch (severity) {
      case "critical":
        return "🚨";
      case "high":
        return "🔴";
      case "medium":
        return "🟡";
      case "low":
        return "✅";
      default:
        return "❓";
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>🔍 사기 탐지 시스템</h2>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px" }}>
        {/* 사기 검사 폼 */}
        <div
          style={{
            backgroundColor: "#f8f9fa",
            padding: "20px",
            borderRadius: "8px",
          }}
        >
          <h3>🔎 사기 점수 계산</h3>
          <form onSubmit={handleCheck}>
            <div style={{ marginBottom: "15px" }}>
              <label style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>
                💰 거래 금액
              </label>
              <input
                type="number"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="예: 150000"
                style={{
                  width: "100%",
                  padding: "8px",
                  border: "1px solid #ccc",
                  borderRadius: "4px",
                  boxSizing: "border-box",
                }}
              />
            </div>

            <div style={{ marginBottom: "15px" }}>
              <label style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>
                📊 시간당 거래 건수
              </label>
              <input
                type="number"
                value={frequency}
                onChange={(e) => setFrequency(e.target.value)}
                placeholder="예: 120"
                style={{
                  width: "100%",
                  padding: "8px",
                  border: "1px solid #ccc",
                  borderRadius: "4px",
                  boxSizing: "border-box",
                }}
              />
            </div>

            <div style={{ marginBottom: "15px" }}>
              <label style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>
                📉 잔액 감소율 (%)
              </label>
              <input
                type="number"
                value={balanceDrain}
                onChange={(e) => setBalanceDrain(e.target.value)}
                placeholder="예: 90"
                max="100"
                min="0"
                style={{
                  width: "100%",
                  padding: "8px",
                  border: "1px solid #ccc",
                  borderRadius: "4px",
                  boxSizing: "border-box",
                }}
              />
            </div>

            <button
              type="submit"
